using System;
#nullable enable
static int CountLeaves(Node? node)
{
    if (node is null) return 0;
    if (node.Left is null && node.Right is null) return 1;
    return CountLeaves(node.Left) + CountLeaves(node.Right);
}
var root = new Node(8, new Node(3, new Node(1)), new Node(10));
Console.WriteLine($"Leaves: {CountLeaves(root)}");
Console.WriteLine($"Empty: {CountLeaves(null)}");
Console.WriteLine($"Single: {CountLeaves(new Node(4))}");
sealed class Node
{
    public int Value { get; }
    public Node? Left { get; }
    public Node? Right { get; }
    public Node(int value, Node? left = null, Node? right = null)
    { Value = value; Left = left; Right = right; }
}

using System;
using System.Collections.Generic;
var next = new Dictionary<string, string[]>
{
    ["A"] = new[] { "B", "C" }, ["B"] = new[] { "D" },
    ["C"] = new[] { "D" }, ["D"] = Array.Empty<string>(), ["E"] = Array.Empty<string>()
};
var distance = new Dictionary<string, int> { ["A"] = 0 };
var previous = new Dictionary<string, string>();
var waiting = new Queue<string>();
waiting.Enqueue("A");
while (waiting.Count > 0)
{
    string current = waiting.Dequeue();
    foreach (string neighbor in next[current])
    {
        if (distance.ContainsKey(neighbor)) continue;
        distance[neighbor] = distance[current] + 1;
        previous[neighbor] = current;
        waiting.Enqueue(neighbor);
        Console.WriteLine($"Discover {neighbor}: distance {distance[neighbor]}, from {current}");
    }
}
Console.WriteLine($"D hops: {distance["D"]}; E reached: {distance.ContainsKey("E")}");

using System;
using System.Collections.Generic;
var neighbors = new Dictionary<string, string[]>
{
    ["A"] = new[] { "B", "C" }, ["B"] = new[] { "A", "D" },
    ["C"] = new[] { "A", "D" }, ["D"] = new[] { "B", "C" }, ["E"] = Array.Empty<string>()
};
var seen = new HashSet<string>();
void Visit(string room, int depth)
{
    seen.Add(room);
    Console.WriteLine($"Enter {room} depth {depth}");
    foreach (string next in neighbors[room])
        if (!seen.Contains(next)) Visit(next, depth + 1);
    Console.WriteLine($"Exit {room}");
}
Visit("A", 0);
Console.WriteLine($"E reached: {seen.Contains("E")}");

using System;
using System.Collections.Generic;
var neighbors = new Dictionary<string, string[]>
{
    ["A"] = new[] { "B", "C" }, ["B"] = new[] { "A", "D" },
    ["C"] = new[] { "A", "D" }, ["D"] = new[] { "B", "C" }, ["E"] = Array.Empty<string>()
};
var component = new Dictionary<string, int>();
void Label(string room, int id)
{
    component[room] = id;
    foreach (string next in neighbors[room])
        if (!component.ContainsKey(next)) Label(next, id);
}
int count = 0;
foreach (string room in new[] { "A", "B", "C", "D", "E" })
    if (!component.ContainsKey(room)) Label(room, ++count);
foreach (string room in new[] { "A", "B", "C", "D", "E" })
    Console.WriteLine($"{room}: component {component[room]}");
Console.WriteLine($"Components: {count}");

using System;
static int Boundary(int[] values, int target, bool upper)
{
    int low = 0, high = values.Length;
    while (low < high)
    {
        int mid = low + (high - low) / 2;
        bool beforeBoundary = values[mid] < target || (upper && values[mid] == target);
        if (beforeBoundary) low = mid + 1;
        else high = mid;
    }
    return low;
}
int[] values = { 2, 4, 4, 4, 7 };
foreach (int target in new[] { 4, 5, 9 })
{
    int first = Boundary(values, target, false);
    int after = Boundary(values, target, true);
    Console.WriteLine($"{target}: [{first},{after}), count {after - first}");
}

using System;
static void QuickSort(int[] data, int low, int high)
{
    if (low >= high) return;
    int left = low, right = high;
    int pivot = data[low + (high - low) / 2];
    while (left <= right)
    {
        while (data[left] < pivot) left++;
        while (data[right] > pivot) right--;
        if (left <= right)
        {
            (data[left], data[right]) = (data[right], data[left]);
            left++; right--;
        }
    }
    if (low < right) QuickSort(data, low, right);
    if (left < high) QuickSort(data, left, high);
}
int[] values = { 5, 2, 5, 1, 8 };
QuickSort(values, 0, values.Length - 1);
Console.WriteLine(string.Join(",", values));
int[] equal = { 4, 4, 4 };
QuickSort(equal, 0, equal.Length - 1);
Console.WriteLine(string.Join(",", equal));

using System;
int[] parent = { 0, 1, 2, 3 }; // A, B, C, isolated D
int[] size = { 1, 1, 1, 1 };
int Find(int vertex)
{
    while (parent[vertex] != vertex) vertex = parent[vertex];
    return vertex;
}
bool Union(int a, int b)
{
    int ra = Find(a), rb = Find(b);
    if (ra == rb) return false;
    if (size[ra] < size[rb]) (ra, rb) = (rb, ra);
    parent[rb] = ra;
    size[ra] += size[rb];
    return true;
}
int cost = 0, components = 4;
foreach (var edge in new[] { (A: 0, B: 1, Cost: 1), (A: 1, B: 2, Cost: 2), (A: 0, B: 2, Cost: 5) })
{
    bool accepted = Union(edge.A, edge.B);
    if (accepted) { cost += edge.Cost; components--; }
    Console.WriteLine($"Cost {edge.Cost}: {(accepted ? "accept" : "reject")}");
}
Console.WriteLine($"Parents: {string.Join(",", parent)}");
Console.WriteLine($"Root A size: {size[Find(0)]}; total {cost}; components {components}");

using System;
using System.Collections.Generic;
var cache = new Dictionary<int, long>();
int calls = 0, hits = 0, computed = 0;
long Fib(int n)
{
    calls++;
    if (n <= 1) return n;
    if (cache.TryGetValue(n, out long saved))
    {
        hits++;
        Console.WriteLine($"Hit F({n})={saved}");
        return saved;
    }
    long value = checked(Fib(n - 1) + Fib(n - 2));
    cache[n] = value;
    computed++;
    Console.WriteLine($"Store F({n})={value}");
    return value;
}
long result = Fib(4);
Console.WriteLine($"F(4)={result}; calls={calls}; hits={hits}; computed={computed}");

