using System;
using System.Collections.Generic;
int[] packs = { 1, 3, 4 };
int target = 6;
int?[] best = new int?[target + 1];
int[] last = new int[target + 1];
best[0] = 0;
for (int amount = 1; amount <= target; amount++)
{
    foreach (int pack in packs)
    {
        if (pack > amount || best[amount - pack] is not int previous) continue;
        int candidate = previous + 1;
        if (!best[amount].HasValue || candidate < best[amount].GetValueOrDefault())
        {
            best[amount] = candidate;
            last[amount] = pack;
        }
    }
    Console.WriteLine($"Amount {amount}: count {best[amount]}, last {last[amount]}");
}
var plan = new List<int>();
if (best[target].HasValue)
    for (int remaining = target; remaining > 0; remaining -= last[remaining])
        plan.Add(last[remaining]);
Console.WriteLine($"Plan: {string.Join("+", plan)}");

using System;
using System.Collections.Generic;
static int[] Direct(string text, string pattern)
{
    var starts = new List<int>();
    for (int start = 0; start <= text.Length - pattern.Length; start++)
    {
        int offset = 0;
        while (offset < pattern.Length && text[start + offset] == pattern[offset]) offset++;
        if (offset == pattern.Length) starts.Add(start);
    }
    return starts.ToArray();
}
Console.WriteLine($"Overlaps: {string.Join(",", Direct("ABABA", "ABA"))}");
Console.WriteLine($"Longer count: {Direct("AB", "ABC").Length}");
Console.WriteLine($"Empty starts: {string.Join(",", Direct("AB", ""))}");

using System;
static int[] Prefix(string pattern)
{
    int[] prefix = new int[pattern.Length];
    int q = 0;
    for (int i = 1; i < pattern.Length; i++)
    {
        while (q > 0 && pattern[i] != pattern[q]) q = prefix[q - 1];
        if (pattern[i] == pattern[q]) q++;
        prefix[i] = q;
    }
    return prefix;
}
Console.WriteLine(string.Join(",", Prefix("ABABACA")));
Console.WriteLine(string.Join(",", Prefix("AAAA")));

using System;
using System.Collections.Generic;
static int[] AllMatches(string text, string pattern)
{
    if (pattern.Length == 0)
    {
        int[] boundaries = new int[text.Length + 1];
        for (int i = 0; i < boundaries.Length; i++) boundaries[i] = i;
        return boundaries;
    }
    int[] prefix = new int[pattern.Length];
    for (int i = 1, q = 0; i < pattern.Length; i++)
    {
        while (q > 0 && pattern[i] != pattern[q]) q = prefix[q - 1];
        if (pattern[i] == pattern[q]) q++;
        prefix[i] = q;
    }
    var starts = new List<int>();
    for (int i = 0, q = 0; i < text.Length; i++)
    {
        while (q > 0 && text[i] != pattern[q]) q = prefix[q - 1];
        if (text[i] == pattern[q]) q++;
        if (q == pattern.Length)
        {
            starts.Add(i - pattern.Length + 1);
            q = prefix[q - 1];
        }
    }
    return starts.ToArray();
}
Console.WriteLine($"Overlaps: {string.Join(",", AllMatches("ABABAB", "ABAB"))}");
Console.WriteLine($"Repeated: {string.Join(",", AllMatches("AAAAA", "AAAA"))}");
Console.WriteLine($"Empty: {string.Join(",", AllMatches("AB", ""))}");
